  'ow.mustFeed': 'صف الخصم فارغ: اختر حفرة تصل إليه.', 'bn.capO': 'أسرتها!', 'bn.slam': 'الضربة الكبرى', 'bn.slamSub': 'لا يُؤسر شيء',
